enum Phase { Menu, Playing, Over }

fn cur(s: i32) -> Phase {
    if s == 0 { Phase::Menu } else { if s == 1 { Phase::Playing } else { Phase::Over } }
}

fn tint(p: Phase) -> i32 {
    match p {
        Phase::Menu => 0x102040,
        Phase::Playing => 0x0a300a,
        Phase::Over => 0x300a0a,
    }
}

fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(1);
    let mut s: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        s = (s + 1) % 3;
        host::display::state_set(0, s);
    }
    host::display::state_set(1, down);
    host::display::clear(tint(cur(s)));
    match s {
        0 => {
            host::display::draw_string(8, 10, "MENU - TAP TO START", 0xffffff, 2);
        }
        1 => {
            host::display::draw_string(8, 10, "PLAYING...", 0x00ff00, 2);
        }
        _ => {
            host::display::draw_string(8, 10, "GAME OVER", 0xff4040, 2);
        }
    }
    host::display::present();
}
